package app;

import app.repositories.EmptyRepository;
import app.repositories.EntryRepository;
import app.repositories.KindRepository;
import app.repositories.MemoryEmptyRepository;
import app.repositories.MemoryEntryRepository;
import app.repositories.MemoryKindRepository;
import app.repositories.MemoryOrderRepository;
import app.repositories.MemoryThingRepository;
import app.repositories.OrderRepository;
import app.repositories.ThingRepository;
import java.util.function.Function;

/** The in-memory repositories, for tests and for trying the services without a database. */
public class MemoryUnitOfWork implements UnitOfWork {
    private final ThingRepository things = new MemoryThingRepository();
    private final KindRepository kinds = new MemoryKindRepository();
    private final OrderRepository order = new MemoryOrderRepository();
    private final EntryRepository entries = new MemoryEntryRepository();
    private final EmptyRepository empties = new MemoryEmptyRepository();

    @Override
    public ThingRepository things() {
        return things;
    }

    @Override
    public KindRepository kinds() {
        return kinds;
    }

    @Override
    public OrderRepository order() {
        return order;
    }

    @Override
    public EntryRepository entries() {
        return entries;
    }

    @Override
    public EmptyRepository empties() {
        return empties;
    }

    /** Memory has no transactions: changes are kept as they are made. */
    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

