package app;

import app.repositories.EmptyRepository;
import app.repositories.EntryRepository;
import app.repositories.KindRepository;
import app.repositories.OrderRepository;
import app.repositories.SqlEmptyRepository;
import app.repositories.SqlEntryRepository;
import app.repositories.SqlKindRepository;
import app.repositories.SqlOrderRepository;
import app.repositories.SqlThingRepository;
import app.repositories.ThingRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import java.util.function.Function;

/** The repositories over one EntityManager, and its transaction. */
public class SqlUnitOfWork implements UnitOfWork {
    private final EntityManager entityManager;
    private final ThingRepository things;
    private final KindRepository kinds;
    private final OrderRepository order;
    private final EntryRepository entries;
    private final EmptyRepository empties;

    public SqlUnitOfWork(EntityManager entityManager) {
        this.entityManager = entityManager;
        this.things = new SqlThingRepository(entityManager);
        this.kinds = new SqlKindRepository(entityManager);
        this.order = new SqlOrderRepository(entityManager);
        this.entries = new SqlEntryRepository(entityManager);
        this.empties = new SqlEmptyRepository(entityManager);
    }

    public EntityManager entityManager() {
        return entityManager;
    }

    @Override
    public ThingRepository things() {
        return things;
    }

    @Override
    public KindRepository kinds() {
        return kinds;
    }

    @Override
    public OrderRepository order() {
        return order;
    }

    @Override
    public EntryRepository entries() {
        return entries;
    }

    @Override
    public EmptyRepository empties() {
        return empties;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        EntityTransaction transaction = entityManager.getTransaction();
        // Joins the transaction already open
        if (transaction.isActive()) return work.apply(this);
        transaction.begin();
        try {
            T result = work.apply(this);
            transaction.commit();
            return result;
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

