/** A row of the "Order" table. */
@Entity(name = "OrderEntity")
@Table(name = "Order", uniqueConstraints = { @UniqueConstraint(columnNames = { "customerName" }) })
@DynamicInsert
@Check(constraints = "\"group\" >= 0")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "Id", nullable = false)
    private Long id;

    @Column(name = "user", nullable = false, length = 40)
    private String user;

    @Column(name = "group", nullable = false)
    @ColumnDefault("0")
    private Integer group;

    @Column(name = "customerName", nullable = false, length = 60)
    private String customerName;

    @Column(name = "class", columnDefinition = "text")
    private String class_;

    @Column(name = "metadata", columnDefinition = "text")
    private String metadata;

    @Column(name = "date")
    private LocalDate date;

    @Column(name = "time")
    private LocalTime time;

    @Column(name = "text", length = 20)
    private String text;

    @Column(name = "list", columnDefinition = "text")
    private String list;

    @Column(name = "str", length = 10)
    private String str;

    @Column(name = "int")
    private Integer int_;

    @Column(name = "dueDate", nullable = false)
    private LocalDate dueDate;

    @Column(name = "closesAt")
    private LocalTime closesAt;

    @Column(name = "createdAt")
    @ColumnDefault("CURRENT_TIMESTAMP")
    private LocalDateTime createdAt;

    @Column(name = "kind_code", length = 10)
    private String kindCode;

    @Column(name = "kind_day")
    private LocalDate kindDay;

    @Column(name = "thing_id")
    private UUID thingId;

    @Column(name = "parentId")
    private Long parentId;

    /** The Thing this row points to (thing_id); read only: the key columns are written. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "thing_id", referencedColumnName = "id", insertable = false, updatable = false)
    @OnDelete(action = OnDeleteAction.SET_NULL)
    private Thing thing;

    /** The Order this row points to (parentId); read only: the key columns are written. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "parentId", referencedColumnName = "Id", insertable = false, updatable = false)
    private Order parentIdRef;

    /** The Kind this row points to (kind_code, kind_day); read only: the key columns are written. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumns(value = { @JoinColumn(name = "kind_code", referencedColumnName = "code", insertable = false, updatable = false), @JoinColumn(name = "kind_day", referencedColumnName = "day", insertable = false, updatable = false) })
