import org.hibernate.annotations.ColumnDefault;
import org.hibernate.annotations.ColumnTransformer;
import org.hibernate.annotations.DynamicInsert;
import org.hibernate.annotations.GeneratedColumn;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

/** A row of the "things" table. */
@Entity
@Table(name = "things")
@DynamicInsert
public class Thing {
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", nullable = false)
    private UUID id;

    @Column(name = "token", nullable = false)
    private UUID token;

    @Column(name = "small", nullable = false)
    private Short small;

    @Column(name = "num")
    private Integer num;

    @Column(name = "big", nullable = false)
    private Long big;

    @Column(name = "price", nullable = false, precision = 10, scale = 2)
    private BigDecimal price;

    @Column(name = "r", nullable = false)
    private Float r;

    @Column(name = "d")
    private Double d;

    @Column(name = "flag", nullable = false)
    @ColumnDefault("true")
    private Boolean flag;

    @Column(name = "born", nullable = false)
    private LocalDate born;

    @Column(name = "opens", nullable = false)
    private LocalTime opens;

    @Column(name = "opens_tz", nullable = false)
    private OffsetTime opensTz;

    @Column(name = "at", nullable = false)
    private LocalDateTime at;

    @Column(name = "at_tz", nullable = false)
    private OffsetDateTime atTz;

    @Column(name = "bin", nullable = false)
    private byte[] bin;

    @Column(name = "data", nullable = false)
    @JdbcTypeCode(SqlTypes.JSON)
    private String data;

    @Column(name = "plain")
    @JdbcTypeCode(SqlTypes.JSON)
    private String plain;

    @Column(name = "feeling", nullable = false, columnDefinition = "\"mood\"")
    @ColumnTransformer(write = "?::\"mood\"")
    private String feeling;

    // "text[]" is kept as its text: {a,b}
    @Column(name = "tags", nullable = false, columnDefinition = "text[]")
    @ColumnTransformer(write = "?::text[]")
    private String tags;

    // "integer[]" is kept as its text: {a,b}
    @Column(name = "numbers", columnDefinition = "integer[]")
    @ColumnTransformer(write = "?::integer[]")
    private String numbers;

    // TODO: "inet" has no JPA type here; it is mapped as text
    @Column(name = "ip", columnDefinition = "inet")
    @ColumnTransformer(write = "?::inet")
    private String ip;

    // TODO: "interval" has no JPA type here; it is mapped as text
    @Column(name = "span", columnDefinition = "interval")
    @ColumnTransformer(write = "?::interval")
    private String span;

    @Column(name = "code", nullable = false, length = 5)
    @JdbcTypeCode(SqlTypes.CHAR)
    private String code;

    @Column(name = "note", columnDefinition = "text")
    private String note;

    @Column(name = "changed")
    @ColumnDefault("CURRENT_TIMESTAMP")
    private OffsetDateTime changed;

    @Column(name = "total", precision = 12, scale = 2, insertable = false, updatable = false)
    @GeneratedColumn("price * 2")
    private BigDecimal total;

    public UUID getId() {
        return id;
    }

    public void setId(UUID id) {
        this.id = id;
    }

    public UUID getToken() {
        return token;
    }

    public void setToken(UUID token) {
        this.token = token;
    }

    public Short getSmall() {
        return small;
    }

    public void setSmall(Short small) {
        this.small = small;
    }

    public Integer getNum() {
        return num;
    }

    public void setNum(Integer num) {
        this.num = num;
    }

    public Long getBig() {
        return big;
    }

    public void setBig(Long big) {
        this.big = big;
    }

    public BigDecimal getPrice() {
        return price;
    }

    public void setPrice(BigDecimal price) {
        this.price = price;
    }

    public Float getR() {
        return r;
    }

    public void setR(Float r) {
        this.r = r;
    }

    public Double getD() {
        return d;
    }

    public void setD(Double d) {
        this.d = d;
