    public LocalDate getBorn() {
        return born;
    }

    public void setBorn(LocalDate born) {
        this.born = born;
    }

    public LocalTime getOpens() {
        return opens;
    }

    public void setOpens(LocalTime opens) {
        this.opens = opens;
    }

    public OffsetTime getOpensTz() {
        return opensTz;
    }

    public void setOpensTz(OffsetTime opensTz) {
        this.opensTz = opensTz;
    }

    public LocalDateTime getAt() {
        return at;
    }

    public void setAt(LocalDateTime at) {
        this.at = at;
    }

    public OffsetDateTime getAtTz() {
        return atTz;
    }

    public void setAtTz(OffsetDateTime atTz) {
        this.atTz = atTz;
    }

    public byte[] getBin() {
        return bin;
    }

