package app.repositories;

import app.common.Page;
import app.entities.Empty;
import app.errors.ConflictException;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import jakarta.persistence.PersistenceException;
import java.util.List;
import java.util.Optional;

/** Keeps empties rows in the database, through an EntityManager. A write joins the transaction already open, or commits at once. */
public class SqlEmptyRepository implements EmptyRepository {
    protected final EntityManager entityManager;

    public SqlEmptyRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public Optional<Empty> findById(Long id) {
        return entityManager.createQuery("select e from EmptyEntity e where e.id = :id", Empty.class).setParameter("id", id)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Page<Empty> list(int offset, int limit) {
        List<Empty> items = entityManager.createQuery("select e from EmptyEntity e order by e.id", Empty.class)
                .setFirstResult(offset)
                .setMaxResults(limit)
                .getResultList();
        long total = entityManager.createQuery("select count(e) from EmptyEntity e", Long.class).getSingleResult();
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public Empty insert(Empty entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Empty", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Empty update(Empty entity) {
        Empty[] stored = new Empty[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Empty", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Empty entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Empty", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

