import org.junit.jupiter.api.Test;

/** Tests of the "empties" table. */
class EmptyTest {
    private EntityManager entityManager;
    /** The repositories over the test database, opened empty for every test */
    private SqlUnitOfWork uow;

    @BeforeEach
    void open() {
        entityManager = TestDatabase.open();
        uow = new SqlUnitOfWork(entityManager);
    }

    @AfterEach
    void close() {
        if (entityManager.getTransaction().isActive()) entityManager.getTransaction().rollback();
        entityManager.close();
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Empty stored = Factories.addEmpty(uow, 1);
            uow.entityManager().clear();
            Empty found = uow.empties().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
        }

        @Test
        void listsRowsByKey() {
            Factories.addEmpty(uow, 1);
            Factories.addEmpty(uow, 2);
            var page = uow.empties().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void storesTheChanges() {
            Empty stored = Factories.addEmpty(uow, 1);
            stored.setNote("changed");
            uow.empties().update(stored);
            uow.entityManager().clear();
            assertEquals("changed", uow.empties().findById(stored.getId()).orElseThrow().getNote());
        }

        @Test
        void isDeleted() {
            Empty stored = Factories.addEmpty(uow, 1);
            uow.empties().delete(stored);
            assertTrue(uow.empties().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class EmptyServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
