            EmptyService service = new EmptyService(uow);
            assertThrows(NotFoundException.class, () -> service.getEmpty(999999L));
        }

        @Test
        void changesARow() {
            EmptyService service = new EmptyService(uow);
            int n = 100;
            Empty row = Factories.newEmpty(1);
            var created = service.createEmpty(createOf(row));
            var updated = service.updateEmpty(created.id(), new EmptyUpdate(Patch.of("changed")));
            assertEquals("changed", updated.note());
