/** Rows for the tests: valid values for every column, and the rows they point to. */
final class Factories {
    private Factories() {}

    /** A valid Thing that is not stored yet; n makes its unique values differ. */
    static Thing newThing(int n) {
        Thing entity = new Thing();
        entity.setToken(UUID.fromString(String.format("00000000-0000-4000-8000-%012d", n)));
        entity.setSmall((short) (n));
        entity.setNum((n));
        entity.setBig((long) (n));
        entity.setPrice(new BigDecimal((n % 10000) + ".50"));
        entity.setR(n + 0.5f);
        entity.setD(n + 0.5);
        entity.setFlag(true);
        entity.setBorn(LocalDate.of(2026, 1, n % 28 + 1));
        entity.setOpens(LocalTime.of(12, n % 60));
        entity.setOpensTz(OffsetTime.of(12, n % 60, 0, 0, ZoneOffset.UTC));
        entity.setAt(LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0));
        entity.setAtTz(OffsetDateTime.of(2026, 1, n % 28 + 1, 12, 0, 0, 0, ZoneOffset.UTC));
        entity.setBin(new byte[] { (byte) n });
        entity.setData("{\"n\": " + n + "}");
        entity.setPlain("{\"n\": " + n + "}");
        entity.setFeeling("sad");
        entity.setTags("{}");
        entity.setNumbers("{}");
        entity.setCode(String.format("%05d", n % 100000));
        entity.setNote("note-" + n);
        return entity;
    }

    /** A stored Thing. */
    static Thing addThing(UnitOfWork uow, int n) {
        Thing entity = newThing(n);
        return uow.things().insert(entity);
    }

    /** A valid Kind that is not stored yet; n makes its unique values differ. */
    static Kind newKind(int n) {
        Kind entity = new Kind();
        entity.setCode("code-" + n);
        entity.setDay(LocalDate.of(2026, 1, n % 28 + 1));
        entity.setLabel("label-" + n);
        return entity;
    }

    /** A stored Kind. */
    static Kind addKind(UnitOfWork uow, int n) {
        Kind entity = newKind(n);
        return uow.kinds().insert(entity);
    }

    /** A valid Order that is not stored yet; n makes its unique values differ. */
