package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.common.Patch;
import app.dtos.ThingCreate;
import app.dtos.ThingUpdate;
import app.entities.Thing;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.ThingService;
import jakarta.persistence.EntityManager;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "things" table. */
class ThingTest {
    private EntityManager entityManager;
    /** The repositories over the test database, opened empty for every test */
    private SqlUnitOfWork uow;

    @BeforeEach
    void open() {
        entityManager = TestDatabase.open();
        uow = new SqlUnitOfWork(entityManager);
    }

    @AfterEach
    void close() {
        if (entityManager.getTransaction().isActive()) entityManager.getTransaction().rollback();
        entityManager.close();
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Thing stored = Factories.addThing(uow, 1);
            uow.entityManager().clear();
            Thing found = uow.things().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
        }

        @Test
        void listsRowsByKey() {
            Factories.addThing(uow, 1);
            Factories.addThing(uow, 2);
            var page = uow.things().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void storesTheChanges() {
            Thing stored = Factories.addThing(uow, 1);
            stored.setNote("changed");
            uow.things().update(stored);
            uow.entityManager().clear();
            assertEquals("changed", uow.things().findById(stored.getId()).orElseThrow().getNote());
        }

        @Test
        void isDeleted() {
            Thing stored = Factories.addThing(uow, 1);
            uow.things().delete(stored);
            assertTrue(uow.things().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class ThingServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            var created = service.createThing(createOf(row));
            var found = service.getThing(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            row.setToken(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createThing(createOf(row)));
            assertEquals(List.of("token"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void saysWhenARowIsMissing() {
            ThingService service = new ThingService(uow);
            assertThrows(NotFoundException.class, () -> service.getThing(UUID.fromString("00000000-0000-4000-8000-000000999999")));
        }

        @Test
        void changesARow() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            var created = service.createThing(createOf(row));
            var updated = service.updateThing(created.id(), new ThingUpdate(Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.of("changed")));
            assertEquals("changed", updated.note());
        }

        @Test
        void deletesARow() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            var created = service.createThing(createOf(row));
            service.deleteThing(created.id());
            assertThrows(NotFoundException.class, () -> service.getThing(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static ThingCreate createOf(Thing row) {
        return new ThingCreate(row.getToken(), row.getSmall(), row.getNum(), row.getBig(), row.getPrice(), row.getR(), row.getD(), row.getFlag(), row.getBorn(), row.getOpens(), row.getOpensTz(), row.getAt(), row.getAtTz(), row.getBin(), row.getData(), row.getPlain(), row.getFeeling(), row.getTags(), row.getNumbers(), row.getIp(), row.getSpan(), row.getCode(), row.getNote());
    }
}
